#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/binding/value/binding_value.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// FlagsValueEditor's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/flags_value_editor.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The flags enumeration the editor offers; a view, since the form properties rebuild it. It must be a valid flags descriptor with at least one positive single-bit choice that can represent the current value (std::invalid_argument otherwise); a change normalizes the value and reopens an open list.
template <typename Declaring>
struct FlagsValueEditorDescriptorCapability {
    PropertyView<PropertyEnumDescriptor, FlagsValueEditorDescriptorCapability<Declaring>> descriptor;

    static void assign(FlagsValueEditorDescriptorCapability& capability, PropertyEnumDescriptor incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.descriptor), std::move(incoming));
    }

    static PropertyEnumDescriptor read(const FlagsValueEditorDescriptorCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        PropertyEnumDescriptor current = control.read_view(capability.descriptor);
        return current;
    }
};

// The checked flags, normalized against descriptor; a view, since the list's checks move it. A value the descriptor cannot represent throws std::invalid_argument.
template <typename Declaring>
struct FlagsValueEditorValueCapability {
    PropertyView<PropertyEnumValue, FlagsValueEditorValueCapability<Declaring>> value;

    static void assign(FlagsValueEditorValueCapability& capability, PropertyEnumValue incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.value), std::move(incoming));
    }

    static PropertyEnumValue read(const FlagsValueEditorValueCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        PropertyEnumValue current = control.read_view(capability.value);
        return current;
    }
};

// Whether the list of flags is open; a view, since the list closes itself. A write opens or closes it and raises drop_down_changed.
template <typename Declaring>
struct FlagsValueEditorDroppedDownCapability {
    PropertyView<bool, FlagsValueEditorDroppedDownCapability<Declaring>> dropped_down;

    static void assign(FlagsValueEditorDroppedDownCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.dropped_down), std::move(incoming));
    }

    static bool read(const FlagsValueEditorDroppedDownCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        bool current = control.read_view(capability.dropped_down);
        return current;
    }
};

// The width of the list of flags, 80 to 1024 (std::invalid_argument otherwise); a change reopens an open list.
template <typename Declaring>
struct FlagsValueEditorOverlayWidthCapability {
    PropertyCell<double, FlagsValueEditorOverlayWidthCapability<Declaring>> overlay_width{240.0};

    static void assign(FlagsValueEditorOverlayWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.overlay_width), incoming);
        if (!capability.overlay_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.overlay_width));
    }
};

// Every FlagsValueEditor capability, in the order the declaring class takes them.
template <typename Declaring>
struct FlagsValueEditorCapabilities : public FlagsValueEditorDescriptorCapability<Declaring>,
                                      public FlagsValueEditorValueCapability<Declaring>,
                                      public FlagsValueEditorDroppedDownCapability<Declaring>,
                                      public FlagsValueEditorOverlayWidthCapability<Declaring> {};

} // namespace gui_forms
